static int8_t relu_requant(int32_t acc, int s) {
    if (acc < 0) acc = 0;
    acc >>= s;
    if (acc > 127) acc = 127;
    return (int8_t)acc;
}
static int8_t sat_requant(int32_t acc, int s) {
    acc >>= s;
    if (acc >  127) acc =  127;
    if (acc < -128) acc = -128;
    return (int8_t)acc;
}

// scratch buffers live in .bss (more SRAM exercise)
static int8_t h1[H1], h2[H2], y_out[OUT];

static void mlp_sw(void) {
    for (int o = 0; o < H1; ++o) {
        int32_t acc = 0;
        for (int i = 0; i < IN; ++i) acc += (int32_t)w1[o*IN+i] * (int32_t)x_test[i];
        h1[o] = relu_requant(acc, SHIFT1);
    }
    for (int o = 0; o < H2; ++o) {
        int32_t acc = 0;
        for (int i = 0; i < H1; ++i) acc += (int32_t)w2[o*H1+i] * (int32_t)h1[i];
        h2[o] = relu_requant(acc, SHIFT2);
    }
    for (int o = 0; o < OUT; ++o) {
        int32_t acc = 0;
        for (int i = 0; i < H2; ++i) acc += (int32_t)w3[o*H2+i] * (int32_t)h2[i];
        y_out[o] = sat_requant(acc, SHIFT3);
    }
}

// --- HW path: SIMD-4 mac_unit2.sv (4-lane dot product, 4 MACs per MAC4 store) -
// Register map (user base 0x2000_0000): 0x00 ACT[W] {a3,a2,a1,a0}, 0x04 MAC4[W]
// {w3,w2,w1,w0} -> acc += sum(a*w), 0x08 CLEAR[W], 0x0C RESULT[R]. Activations
// load resident; each MAC4 streams a weight quad. All layer dims are multiples
// of 4, so each dot tiles into n/4 (ACT,MAC4) pairs. ReLU/requant stay in SW.
#ifdef __riscv
#define MAC2_BASE   (0x20000000UL)
#define MAC2_ACT    (*((volatile uint32_t *)(MAC2_BASE + 0x00)))
#define MAC2_MAC4   (*((volatile uint32_t *)(MAC2_BASE + 0x04)))
#define MAC2_CLEAR  (*((volatile uint32_t *)(MAC2_BASE + 0x08)))
#define MAC2_RESULT (*((volatile int32_t  *)(MAC2_BASE + 0x0C)))
static inline uint32_t pack4(const int8_t *p) {
    return (uint32_t)(uint8_t)p[0]        | ((uint32_t)(uint8_t)p[1] << 8)
         | ((uint32_t)(uint8_t)p[2] << 16) | ((uint32_t)(uint8_t)p[3] << 24);
}
// length-n (n % 4 == 0) dot product through the SIMD-4 engine
static int32_t mac2_dot(const int8_t *a, const int8_t *w, int n) {
    MAC2_CLEAR = 0;
    for (int q = 0; q < n; q += 4) { MAC2_ACT = pack4(a + q); MAC2_MAC4 = pack4(w + q); }
    return (int32_t)MAC2_RESULT;
}

static int8_t h1_hw[H1], h2_hw[H2], y_hw[OUT];

static void mlp_hw(void) {
    for (int o = 0; o < H1;  ++o) h1_hw[o] = relu_requant(mac2_dot(x_test, &w1[o*IN], IN), SHIFT1);
    for (int o = 0; o < H2;  ++o) h2_hw[o] = relu_requant(mac2_dot(h1_hw, &w2[o*H1], H1), SHIFT2);
    for (int o = 0; o < OUT; ++o) y_hw[o]  = sat_requant (mac2_dot(h2_hw, &w3[o*H2], H2), SHIFT3);
}
#endif

int main(void) {
    uart_init();

    uint32_t t0 = read_mcycle();
    mlp_sw();
    uint32_t cyc_sw = read_mcycle() - t0;

    print_vec("SW y=",   y_out,  OUT);
    print_vec("golden=", GOLDEN, OUT);
    print_str("SW cyc="); print_int((int32_t)cyc_sw); uart_write('\n');

    int pass = 1;
    for (int i = 0; i < OUT; ++i) if (y_out[i] != GOLDEN[i]) pass = 0;

#ifdef __riscv
    uint32_t t1 = read_mcycle();
    mlp_hw();
    uint32_t cyc_hw = read_mcycle() - t1;

    print_vec("HW y=", y_hw, OUT);
    print_str("HW cyc="); print_int((int32_t)cyc_hw); uart_write('\n');
    for (int i = 0; i < OUT; ++i) if (y_hw[i] != GOLDEN[i]) pass = 0;

    if (cyc_hw < cyc_sw) { print_str("MAC faster by "); print_int((int32_t)(cyc_sw - cyc_hw)); }
    else                 { print_str("Core faster by "); print_int((int32_t)(cyc_hw - cyc_sw)); }
    print_str(" cyc\n");
#endif

    print_str(pass ? "PASS\n" : "FAIL\n");

    uart_write_flush();
    return pass ? 0 : 1;
}
